def write(path,title,content,description='Găsește, înțelege, verifică și citează angajamentele de aderare ale Republicii Moldova.'):
 target=OUT/(path.lstrip('/')+'index.html' if path.endswith('/') else path.lstrip('/'));target.parent.mkdir(parents=True,exist_ok=True)
 page=(R/'templates/shell.html').read_text().replace('__TITLE__',esc(title+' · pna/eu')).replace('__DESCRIPTION__',esc(description)).replace('__CONTENT__',content).replace('pna.md · v0.1','pna.md · ediție documentată')
 target.write_text(page)
def dump(path,data):
 p=OUT/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(data,ensure_ascii=False,separators=(',',':')))
