home=(R/'templates/home.html').read_text().replace('__TOPICS__',''.join(f'<a class="topic" href="/exploreaza/?tema={k}"><span>{v}</span><span aria-hidden="true">→</span></a>' for k,v in TOPICS.items())).replace('__FEATURED__',''.join(card(next(a for a in A if a['id']==i)) for i in ['fdi-b-25-2026-09-10','26-b-22-2026-09-10']))
