write('/exploreaza/','Explorează programul',workspace('<p class="eyebrow">De la întrebare la sursă</p><h1>Explorează programul</h1><p>Caută în formulările acțiunilor, instituții și indicatori. Pentru contextul narativ complet, folosește <a href="/surse/">căutarea în documente</a>.</p><form id="explorer"><label for="query">Ce cauți?</label><div class="search"><input id="query" name="q" type="search" placeholder="De exemplu: școli, consultări, energie"><button class="primary">Caută</button></div>'+filters+'<a href="/exploreaza/">Resetează filtrele</a></form>'+coverage+'<p class="meta">Temele sunt orientative și atribuite după capitol; unele acțiuni ating mai multe teme.</p><p id="results-count" role="status">Se încarcă indexul…</p><p id="load-error" hidden></p><div id="results" class="action-grid"></div><p id="empty-results" hidden>Nicio acțiune găsită. Încearcă mai puține filtre sau caută în documente.</p><div class="actions"><button id="previous" class="secondary">← Înapoi</button><span id="page-count"></span><button id="next" class="secondary">Mai departe →</button></div><p><a id="export-results" href="/exports/actions.csv" download>Descarcă rezultatele CSV</a> · <a href="/exports/actions.json">Datele complete și dovezile (JSON)</a></p><noscript><p>Folosește <a href="/capitole/">lista pe capitole</a> pentru acces fără JavaScript.</p></noscript>'))
