dump('index-actions.json',index);dump('exports/actions.json',A);dump('exports/documents.json',D)
b=io.StringIO();w=csv.writer(b);w.writerow(['ID','Capitol','Anexa','Număr','Formulare','Instituție','Termen','Revizuire','Sursă','Pagina'])
for a in A:w.writerow([a['id'],a['chapter'],a['annex'],a['number'],a['original'],a['institution'],a['deadline'],a['publicationStatus'],DOC[a['sourceId']]['url'],a['page']])
