chapterlinks=''.join(f'<a class="chapter-link" href="/capitol/{c}/">{esc(chapter_name(c))}<small>{sum(a["chapter"]==c for a in A)} acțiuni · {sum(str(d["chapter"])==c for d in D)} documente</small></a>' for c in CHAPTERS)
