 write(f'/document/{d["id"]}/',d['title'],workspace(f'<h1>{esc(d["title"])}</h1><p>{d["pages"]} pagini · copie păstrată la 10.09.2026</p><div class="actions"><a class="primary" href="{d["local"]}">Deschide PDF-ul integral</a><a href="{esc(d["url"])}">Sursa oficială ↗</a></div><p class="coverage">Textul extras păstrează contextul paginilor, dar poate pierde ordinea coloanelor, celulele unite și notele. PDF-ul este reperul pentru citare. Atribuirea juridică la ultima anexă adoptată așteaptă verificare.</p><details><summary>Identificarea exactă a copiei</summary><p class="source-reference">SHA-256: {d["sha256"]}</p><p>Ediție: {esc(d["editionId"])}</p><p><a href="/exports/documents.json">Manifestul tuturor documentelor</a></p></details><h2>Context, tabele și note</h2>'+pages))
